// Ekran, który pacjent widzi po wysłaniu formularza: odpowiedź (albo informacja, że sprawę przejął zespół).
// The screen the patient sees after sending the form: the reply (or a note that the team took over).
// Czytamy z bramki jakości, bo ona zawsze ma dane (wyjście IF jest puste na jednej z ścieżek).
// We read from the quality gate because it always has data (one output of the IF is empty on each path).
const p = $('Bramka jakości (Python) / Quality gate (Python)').first().json;
const cfg = p.settings;
const auto = p.gate.decision === 'auto';

function esc(s) { return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }

const box = 'background:#f1f8f9;border:1px solid #d7e7ea;border-radius:12px;padding:16px 18px;line-height:1.6;font-size:15px';
const code = '<div style="margin-top:16px;padding:12px 16px;border-radius:12px;background:#0e8c9b;color:#ffffff;font-weight:600;letter-spacing:0.04em">Kod zgłoszenia / Request code: ' + esc(p.ticket_code) + '</div>';
const how = '<p style="margin:14px 0 0;font-size:13px;color:#52717a;line-height:1.5">Aby wrócić do rozmowy, otwórz formularz ponownie, wybierz „Wracam do mojej wizyty” i podaj ten sam e-mail oraz telefon.<br>To continue the conversation, open the form again, choose "Returning to my appointment" and enter the same e-mail and phone.</p>';

let content = '';
if (auto) {
  content = '<p style="margin:0 0 8px;font-size:14px;color:#52717a">Odpowiedź Nova Smile / Nova Smile reply</p>'
    + '<div style="' + box + '">' + esc(p.reply.body).replace(/\n/g, '<br>') + '</div>'
    + code
    + '<p style="margin:12px 0 0;font-size:13px;color:#52717a">Kopię wysłaliśmy też na Twój e-mail. / We also sent a copy to your e-mail.</p>'
    + how;
} else {
  const emergency = p.gate.is_emergency
    ? '<div style="margin-bottom:16px;padding:14px 16px;border-radius:12px;background:#fdecec;border:1px solid #f3b8b8;color:#8a1f1f;line-height:1.5"><b>Sytuacja pilna? / Urgent?</b><br>Zadzwoń na dyżur: ' + esc(cfg.emergency_phone) + '. W zagrożeniu życia dzwoń 112.<br>Call the on-call line: ' + esc(cfg.emergency_phone) + '. If life is at risk, call 112.</div>'
    : '';
  content = emergency
    + '<div style="' + box + '"><b>Dziękujemy! Przekazaliśmy Twoją sprawę zespołowi.</b><br>Odpowiedź dostaniesz e-mailem najszybciej, jak to możliwe.<br><br><b>Thank you! We have passed your request to our team.</b><br>You will receive a reply by e-mail as soon as possible.</div>'
    + code + how;
}

// Karta w kolorach kliniki, taka sama jak formularz.
// A card in the clinic colours, matching the form.
const html = '<div style="background:#eef6f7;padding:28px 14px;min-height:100vh;box-sizing:border-box;font-family:Inter,Segoe UI,Arial,sans-serif;color:#0b3b46">'
  + '<div style="max-width:560px;margin:0 auto;background:#ffffff;border:1px solid #d7e7ea;border-radius:16px;box-shadow:0 8px 24px rgba(14,116,128,0.10);overflow:hidden">'
  + '<div style="background:#0e8c9b;color:#ffffff;padding:16px 24px;font-size:18px;font-weight:600">Nova Smile</div>'
  + '<div style="padding:24px">' + content + '</div></div></div>';

return [{ json: { final_html: html } }];

// Wiadomość na Telegram dla człowieka: kto pisze, dlaczego sprawa trafiła do człowieka i jaki jest szkic odpowiedzi.
// The Telegram message for the human: who is writing, why a human is needed and what the draft reply is.
const ticket = $('Pobierz zgłoszenie do decyzji / Load ticket for decision').first().json;
const rows = $input.all().map(function (i) { return i.json; }).filter(function (r) { return r.body; });

const drafts = rows.filter(function (r) { return r.direction === 'assistant' && r.status === 'pending_approval'; });
const patientMsgs = rows.filter(function (r) { return r.direction === 'patient'; });
if (!drafts.length) { throw new Error('No pending draft for ' + ticket.ticket_code); }

const draft = drafts[drafts.length - 1];
const patient = patientMsgs.length ? patientMsgs[patientMsgs.length - 1] : { body: '' };
const emergency = draft.decision === 'emergency';

function cut(s, n) { s = String(s || ''); return s.length > n ? s.slice(0, n - 1) + '…' : s; }

const lines = [
  (emergency ? '🚨 PILNE / URGENT · ' : '🦷 ') + 'Nova Smile · potrzebna decyzja / decision needed',
  '',
  'Zgłoszenie / Ticket: ' + ticket.ticket_code,
  'Pacjent / Patient: ' + ticket.patient_name + ' · ' + String(ticket.language || '').toUpperCase(),
  '',
  'Dlaczego człowiek? / Why a human?',
  cut(draft.risk_reasons || '-', 600),
  '',
  'Wiadomość pacjenta / Patient message:',
  '„' + cut(patient.body, 700) + '”',
  '',
  'Szkic odpowiedzi / Draft reply:',
  cut(draft.body, 1400),
  '',
  'Naciśnij przycisk poniżej, aby zdecydować. / Tap the button below to decide.'
];

return [{ json: {
  ticket_code: ticket.ticket_code,
  patient_email: ticket.email,
  patient_name: ticket.patient_name,
  language: ticket.language,
  draft_text: draft.body,
  emergency: emergency,
  telegram_text: lines.join('\n')
} }];

// Zamieniamy odpowiedź z formularza na prostą decyzję: approve / edit / reject / expired.
// We turn the form answer into a simple decision: approve / edit / reject / expired.
const ctx = $('Przygotuj wiadomość dla zespołu / Build staff message').first().json;
const r = $input.first().json || {};

// Zbieramy wszystkie teksty z odpowiedzi, niezależnie od tego, jak formularz je opakował.
// We collect every text from the answer, no matter how the form wrapped it.
const answers = [];
function walk(node, key) {
  if (node === null || node === undefined) return;
  if (typeof node === 'string') { answers.push({ key: key, value: node }); return; }
  if (typeof node === 'object') { Object.keys(node).forEach(function (k) { walk(node[k], k); }); }
}
walk(r, '');

// 1) Decyzja: która z trzech opcji została wybrana
// 1) Decision: which of the three options was chosen
const decisionHit = answers.find(function (a) {
  return a.value.length < 120 && /zatwierd|approve and send|popraw|edited version|odrzu|reject, do not send/i.test(a.value);
});
const decisionRaw = decisionHit ? decisionHit.value : '';

// 2) Tekst odpowiedzi (przydatny przy wersji poprawionej)
// 2) The reply text (used for the edited version)
let textRaw = '';
const byKey = answers.find(function (a) { return /tre[sś][cć]|reply text/i.test(a.key); });
if (byKey) {
  textRaw = byKey.value.trim();
} else {
  const others = answers
    .filter(function (a) { return a !== decisionHit && a.value.length > 40; })
    .sort(function (x, y) { return y.value.length - x.value.length; });
  if (others.length) textRaw = others[0].value.trim();
}

let action = 'expired';                                   // brak odpowiedzi w limicie czasu / no answer within the time limit
if (/zatwierd|approve and send/i.test(decisionRaw)) action = 'approve';
else if (/popraw|edited version/i.test(decisionRaw)) action = 'edit';
else if (/odrzu|reject/i.test(decisionRaw)) action = 'reject';

let finalText = '';
if (action === 'approve') finalText = ctx.draft_text;
if (action === 'edit') finalText = textRaw || ctx.draft_text;

return [{ json: { action: action, final_text: finalText, ticket_code: ctx.ticket_code } }];

// E-mail z odpowiedzią zatwierdzoną przez człowieka.
// The e-mail with the reply approved by a human.
const ctx = $('Przygotuj wiadomość dla zespołu / Build staff message').first().json;
const d = $input.first().json;
const lang = ctx.language === 'pl' ? 'pl' : 'en';
const formUrl = 'https://YOUR-N8N-HOST/form/nova-smile-support';

function esc(s) { return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
const paragraphs = esc(d.final_text).split('\n\n').map(function (par) {
  return '<p style="margin:0 0 14px;line-height:1.6">' + par.replace(/\n/g, '<br>') + '</p>';
}).join('');

const html = '<div style="background:#eef6f7;padding:24px;font-family:Segoe UI,Arial,sans-serif;color:#0b3b46">'
  + '<div style="max-width:560px;margin:0 auto;background:#ffffff;border:1px solid #d7e7ea;border-radius:16px;overflow:hidden">'
  + '<div style="background:#0e8c9b;color:#ffffff;padding:18px 24px;font-size:18px;font-weight:600">Nova Smile</div>'
  + '<div style="padding:24px;font-size:15px">' + paragraphs
  + '<div style="margin:18px 0;padding:12px 16px;border-radius:12px;background:#f1f8f9;border:1px solid #d7e7ea"><b>Kod zgłoszenia / Request code: ' + esc(d.ticket_code) + '</b></div>'
  + '<p style="font-size:13px;color:#52717a;line-height:1.5;margin:0">Aby wrócić do rozmowy, otwórz formularz, wybierz „Wracam do mojej wizyty” i podaj ten sam e-mail oraz telefon.<br>To continue the conversation, open the form, choose "Returning to my appointment" and enter the same e-mail and phone.<br><a href="' + formUrl + '" style="color:#0e8c9b">' + formUrl + '</a></p>'
  + '</div>'
  + '<div style="padding:14px 24px;background:#f7fafb;font-size:12px;color:#7a8f95;line-height:1.5">Odpowiedź zatwierdzona przez zespół Nova Smile. / Reply approved by the Nova Smile team.</div>'
  + '</div></div>';

return [{ json: {
  to: ctx.patient_email,
  subject: lang === 'pl' ? 'Nova Smile – odpowiedź na Twoją wiadomość' : 'Nova Smile – reply to your message',
  html: html,
  ticket_code: d.ticket_code,
  final_text: d.final_text,
  action: d.action
} }];

// Pilne sprawy przypominamy po 10 minutach, zwykłe po 60.
// Urgent cases are reminded after 10 minutes, normal ones after 60.
const LIMIT_URGENT = 10;
const LIMIT_NORMAL = 60;
const now = Date.now();
const out = [];

for (const item of $input.all()) {
  const t = item.json;
  if (!t.ticket_code || !t.waiting_since) continue;
  const waited = Math.round((now - new Date(t.waiting_since).getTime()) / 60000);
  const urgent = t.urgency === 'emergency' || t.urgency === 'high';
  const limit = urgent ? LIMIT_URGENT : LIMIT_NORMAL;
  if (waited >= limit) {
    out.push({ json: { ticket_code: t.ticket_code, patient_name: t.patient_name, urgent: urgent, waited_min: waited, limit_min: limit, summary: t.last_summary || '' } });
  }
}

return out;
